let fenced = false;
for (const line of body.split(/\r?\n/)) {
  if (/^\s*(?:```|~~~)/.test(line)) fenced = !fenced;
  const heading = fenced ? null : HEADING.exec(line);
  if (heading) {
    close();
    current = normalize(heading[1] ?? '');
    lines = [];
  } else {
    lines.push(line);
  }
}
